          }
        }
      } catch {
        // cross-origin, can't inspect
      }
    }
  }, [updateNavState]);

  const tryInjectScript = useCallback((script: string) => {
    const iframe = iframeRef.current;
    if (!iframe?.contentWindow) return;
    try {
