function AccountCard({
  account,
  onSelect,
  onToggleFavorite,
  onDelete,
  onCopy,
  onOpen,
  copiedField,
}: {
  account: TempEmailAccount;
  onSelect: (a: TempEmailAccount) => void;
  onToggleFavorite: () => void;
  onDelete: () => void;
  onCopy: (text: string, field: string) => void;
  onOpen: () => void;
  copiedField: string | null;
}) {
  const fullAddress = `${account.username}@${account.domain}`;

  return (
    <div
      className="group relative rounded-lg border border-border bg-card p-3 transition-colors hover:bg-accent/50 cursor-pointer"
      onClick={() => onSelect(account)}
    >
      <div className="flex items-start justify-between gap-3">
        <div className="min-w-0 flex-1">
          <div className="flex items-center gap-2">
            <code className="truncate text-sm font-mono font-medium">{fullAddress}</code>
            {account.isFavorite && (
              <Star className="h-3.5 w-3.5 shrink-0 fill-yellow-400 text-yellow-400" />
            )}
          </div>
          {account.note && (
            <p className="mt-0.5 truncate text-xs text-muted-foreground">{account.note}</p>
          )}
          <div className="mt-1 flex items-center gap-2">
            <Badge variant="secondary" className="text-[10px]">
              {formatDate(account.createdAt)}
            </Badge>
          </div>
        </div>
        <div className="flex shrink-0 gap-1 opacity-0 transition-opacity group-hover:opacity-100">
          <Button
            variant="ghost"
            size="icon"
            className="h-7 w-7"
            onClick={(e) => {
              e.stopPropagation();
              onCopy(fullAddress, account.id);
            }}
          >
            {copiedField === account.id ? (
              <Check className="h-3.5 w-3.5 text-emerald-400" />
            ) : (
              <Copy className="h-3.5 w-3.5" />
            )}
          </Button>
          <Button
            variant="ghost"
            size="icon"
            className="h-7 w-7"
            onClick={(e) => {
              e.stopPropagation();
              onOpen();
            }}
          >
            <ExternalLink className="h-3.5 w-3.5" />
          </Button>
          <Button
            variant="ghost"
            size="icon"
            className="h-7 w-7"
            onClick={(e) => {
              e.stopPropagation();
              onToggleFavorite();
            }}
          >
            <Star
              className={`h-3.5 w-3.5 ${
                account.isFavorite ? "fill-yellow-400 text-yellow-400" : ""
              }`}
            />
          </Button>
          <Button
            variant="ghost"
            size="icon"
            className="h-7 w-7 text-destructive hover:text-destructive"
            onClick={(e) => {
              e.stopPropagation();
              onDelete();
            }}
          >
            <Trash2 className="h-3.5 w-3.5" />
          </Button>
        </div>
      </div>
    </div>
  );
}

