@tailwind base;
@tailwind components;
@tailwind utilities;

@layer base {
  :root {
    --background: 220 20% 6%;
    --foreground: 210 20% 96%;

    --card: 220 18% 8%;
    --card-foreground: 210 20% 96%;

    --popover: 220 18% 8%;
    --popover-foreground: 210 20% 96%;

    --primary: 180 70% 45%;
    --primary-foreground: 220 20% 6%;

    --secondary: 220 15% 15%;
    --secondary-foreground: 210 20% 96%;

    --muted: 220 15% 15%;
    --muted-foreground: 215 15% 55%;

    --accent: 220 15% 15%;
    --accent-foreground: 210 20% 96%;

    --destructive: 0 70% 50%;
    --destructive-foreground: 210 20% 96%;

    --border: 220 15% 18%;
    --input: 220 15% 18%;
    --ring: 180 70% 45%;

    --radius: 0.625rem;

    --sidebar-background: 220 18% 8%;
    --sidebar-foreground: 210 20% 96%;
    --sidebar-primary: 180 70% 45%;
    --sidebar-primary-foreground: 220 20% 6%;
    --sidebar-accent: 220 15% 15%;
    --sidebar-accent-foreground: 210 20% 96%;
    --sidebar-border: 220 15% 18%;
    --sidebar-ring: 180 70% 45%;
  }
}

@layer base {
  * {
    @apply border-border;
  }

  body {
    @apply bg-background text-foreground;
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
  }

  /* Scrollbar styling for webkit */
  ::-webkit-scrollbar {
    width: 6px;
    height: 6px;
  }

  ::-webkit-scrollbar-track {
    background: transparent;
  }

  ::-webkit-scrollbar-thumb {
    background: hsl(var(--border));
    border-radius: 3px;
  }

  ::-webkit-scrollbar-thumb:hover {
    background: hsl(var(--muted-foreground));
  }
}

@layer utilities {
  .text-cyan-300 {
    color: #67e8f9;
  }

  .text-cyan-400 {
    color: #22d3ee;
  }

  .bg-cyan-600 {
    background-color: #0891b2;
  }

  .bg-cyan-700 {
    background-color: #0e7490;
  }

  .hover\:bg-cyan-700:hover {
    background-color: #0e7490;
  }

  .text-emerald-400 {
    color: #34d399;
  }
}

